const rows = $input.all().map(x=>x.json||{}).filter(r=>r['Candidate ID']);
const count = {};
for (const r of rows) {
 const s=String(r.Status||'Unknown');
 count[s]=(count[s]||0)+1;
}
const scores=rows.map(r=>Number(r['Match Score'])).filter(n=>Number.isFinite(n));
const avg=scores.length ? Math.round(scores.reduce((a,b)=>a+b,0)/scores.length) : 0;
const duplicates=rows.filter(r=>String(r['Potential Duplicate']).toUpperCase()==='YES').length;
const pending=rows.filter(r=>String(r.Status||'').includes('Pending') || String(r.Status||'').includes('Manual Review')).length;
const lines=Object.entries(count).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,v])=>`- ${k}: ${v}`);
const report=[
`Recruitment pipeline — ${new Date().toLocaleString('en-PK',{timeZone:'Asia/Karachi'})}`,
`Total applications: ${rows.length}`,
`Average rubric match score: ${avg}/100 (advisory only)`,
`Potential duplicate records: ${duplicates}`,
`Awaiting recruiter review: ${pending}`,
'',
'Pipeline by status:',
...(lines.length?lines:['- No candidate records found.']),
'',
'Reminder: AI scores are decision-support signals. Hiring decisions require human review.'
].join('\\n');
return [{json:{report,total:rows.length,averageScore:avg,duplicates,pending}}];
